import{_ as t,c as e,o as s,b2 as n}from"./chunks/framework.CUhoHPxN.js";const h=JSON.parse('{"title":"C7JsonTableColumn（C7 JSON 表格列）设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-08-c7-json-table-column-design.md","filePath":"superpowers/specs/2026-05-08-c7-json-table-column-design.md"}'),r={name:"superpowers/specs/2026-05-08-c7-json-table-column-design.md"};function d(c,o,l,a,g,i){return s(),e("div",null,[...o[0]||(o[0]=[n('<h1 id="c7jsontablecolumn-c7-json-表格列-设计说明" tabindex="-1">C7JsonTableColumn（C7 JSON 表格列）设计说明 <a class="header-anchor vp-link" href="#c7jsontablecolumn-c7-json-表格列-设计说明" aria-label="Permalink to &quot;C7JsonTableColumn（C7 JSON 表格列）设计说明&quot;">​</a></h1><p><strong>日期</strong>：2026-05-08<br><strong>状态</strong>：已定稿（经 brainstorming 澄清 <strong>1B、2B、3B、4A、5A</strong> 与「设计确认」）<br><strong>依据</strong>：<code>原始需求/前端/C7JSON表格列.md</code>、<code>原始需求/前端/C7JSON表格.md</code>（边界参考）<br><strong>实现路径</strong>：首版 <strong>单文件 <code>index.vue</code></strong>（<code>v-for</code> + 按 <code>columnType</code> 分支）；若逻辑膨胀再抽 <strong><code>normalizeColumns.ts</code></strong>。</p><hr><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><ul><li><strong>背景</strong>：列表列渲染重复（字典标签、图片预览、链接、具名 slot 等），与父级 <strong>C7JsonTable</strong> 的 <strong><code>tableColumns[]</code></strong> 方向一致。</li><li><strong>目标</strong>：提供 <strong><code>C7JsonTableColumn</code></strong>：根据 <strong><code>columns</code></strong> 生成 <strong><code>ElTableColumn</code></strong> 集合；内置 <strong><code>columnType</code></strong> 渲染；支持 <strong><code>#header-${prop}</code></strong> 列头插槽；可在 <strong>任意 <code>ElTable</code></strong> 中单独使用，也可被未来 <strong>C7JsonTable</strong> 引用。</li><li><strong>非目标</strong>：搜索区、分页、列持久化、批量操作；<strong>多选列 / 序号列</strong>（由父级自行声明 <strong><code>el-table-column type=&quot;selection&quot;</code></strong> 等）；树表懒加载实现细节。</li></ul><hr><h2 id="_2-命名、边界与落点" tabindex="-1">2. 命名、边界与落点 <a class="header-anchor vp-link" href="#_2-命名、边界与落点" aria-label="Permalink to &quot;2. 命名、边界与落点&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>约定</th></tr></thead><tbody><tr><td><strong>对外组件名</strong></td><td><strong><code>C7JsonTableColumn</code></strong></td></tr><tr><td><strong>目录</strong></td><td><strong><code>quick-ui/src/packages/C7JsonTableColumn/index.vue</code></strong></td></tr><tr><td><strong>根节点</strong></td><td><strong>多个 <code>el-table-column</code></strong>（Vue 3 <strong>Fragment 多根</strong>），父级写法：<code>&lt;el-table&gt;&lt;C7JsonTableColumn :columns=&quot;cols&quot; /&gt;…&lt;/el-table&gt;</code>。</td></tr><tr><td><strong>全局注册</strong></td><td><strong><code>quick-ui/src/packages/index.js</code></strong>：<strong><code>export</code></strong> + <strong><code>installPackages</code></strong>。</td></tr></tbody></table></div><p><strong>职责</strong>：列过滤、排序、常用属性透传、按 <strong><code>columnType</code></strong> 渲染单元格与列头转发。</p><p><strong>不负责</strong>：表格数据请求、行选择状态、列显隐持久化（属 JsonTable 或其它父级）。</p><hr><h2 id="_3-对外-props" tabindex="-1">3. 对外 Props <a class="header-anchor vp-link" href="#_3-对外-props" aria-label="Permalink to &quot;3. 对外 Props&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>Prop</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><strong><code>columns</code></strong></td><td><code>Array</code></td><td><strong>必填</strong>；列描述对象见 <strong>第 4 节</strong>。非法非数组：不渲染列，<strong>开发环境 <code>console.warn</code></strong>。</td></tr><tr><td><strong><code>emptyText</code></strong></td><td><code>string</code></td><td><strong>可选</strong>；表级默认空文案，供 <strong><code>columnType===&#39;text&#39;</code></strong> 且列上 <strong>未写 <code>emptyText</code></strong> 时使用。</td></tr></tbody></table></div><hr><h2 id="_4-列描述对象" tabindex="-1">4. 列描述对象 <a class="header-anchor vp-link" href="#_4-列描述对象" aria-label="Permalink to &quot;4. 列描述对象&quot;">​</a></h2><h3 id="_4-1-过滤与排序" tabindex="-1">4.1 过滤与排序 <a class="header-anchor vp-link" href="#_4-1-过滤与排序" aria-label="Permalink to &quot;4.1 过滤与排序&quot;">​</a></h3><ul><li><strong><code>visible !== false</code></strong> 的列才渲染（默认展示）。</li><li><strong><code>order</code></strong>：<strong>数值升序</strong>；<strong>未设置 <code>order</code> 的列排在后面</strong>；<strong><code>order</code> 相同</strong>时保持 <strong><code>columns</code> 数组中的原始相对顺序</strong>（稳定排序）。</li></ul><h3 id="_4-2-透传到-el-table-column" tabindex="-1">4.2 透传到 <code>el-table-column</code> <a class="header-anchor vp-link" href="#_4-2-透传到-el-table-column" aria-label="Permalink to &quot;4.2 透传到 `el-table-column`&quot;">​</a></h3><p>以下字段若存在则绑定到 <strong><code>el-table-column</code></strong>（与 Element Plus 一致）：</p><p><strong><code>prop</code>、<code>label</code>、<code>width</code>、<code>minWidth</code>、<code>fixed</code>、<code>align</code>、<code>headerAlign</code>、<code>sortable</code>、<code>showOverflowTooltip</code></strong></p><p><strong><code>props</code>（需求名）</strong>：表示「其余列级属性」对象，实现时建议内部变量名 <strong><code>columnProps</code></strong> 或文档明确 <strong><code>props</code> 键</strong>，以 <strong><code>v-bind</code> 合并</strong>到 <strong><code>el-table-column</code></strong>，用于前表未列出的 EP 列属性（如 <strong><code>class-name</code></strong>、<strong><code>resizable</code></strong> 等，以 EP 文档为准）。</p><h3 id="_4-3-columntype-默认-text" tabindex="-1">4.3 <code>columnType</code>（默认 <strong><code>text</code></strong>） <a class="header-anchor vp-link" href="#_4-3-columntype-默认-text" aria-label="Permalink to &quot;4.3 `columnType`（默认 **`text`**）&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th><code>columnType</code></th><th>行为</th></tr></thead><tbody><tr><td><strong><code>text</code></strong>（默认）</td><td>若配置了 <strong><code>formatter</code></strong>：签名与 EP 一致 <strong><code>(row, column, cellValue, index) =&gt; string</code></strong>，<strong>直接传给 <code>el-table-column</code> 的 <code>formatter</code></strong>，<strong>不在此路径上自动套 <code>emptyText</code></strong>（<strong>4A</strong>）。若 <strong>未配置 <code>formatter</code></strong>：按 <strong><code>prop</code></strong> 取 <strong><code>cellValue</code></strong>；若为空（<strong><code>null</code> / <code>undefined</code> / &#39;&#39;<code>**；**不含**仅空白字符串，除非后续 JsonTable 另有约定——本文档固定为 **三者**）则展示 **列级 </code>emptyText<code>?? 表级</code>emptyText<code>（第 3 节）?? </code>&#39;-&#39;`</strong>（实现可统一为常量，须在代码注释与本文保持一致）。</td></tr><tr><td><strong><code>tag</code></strong></td><td><strong><code>C7DictTag</code></strong>：<strong><code>modelValue</code></strong> = 行字段值（<strong><code>prop</code> 必填</strong>）；<strong><code>options</code></strong> = <strong><code>col.options ?? col.dictList</code></strong>（<strong><code>options</code> 优先于 <code>dictList</code></strong>，<strong>2B</strong>）。其它 <strong><code>C7DictTag</code></strong> 属性（如 <strong><code>dictType</code>、<code>separator</code>、<code>showValue</code>、<code>max</code></strong>）允许在列对象上同名透传，或通过 <strong><code>columnProps</code>/扩展字段</strong> 传入（实现以「少魔法、文档示例为准」）。</td></tr><tr><td><strong><code>image</code></strong></td><td><strong><code>C7Preview</code></strong>：<strong><code>urls</code></strong> 绑定 <strong><code>row[prop]</code></strong>（<strong>string</strong>，与 <strong>C7Preview</strong> 首版逗号分隔一致）；<strong><code>coverType=&#39;none&#39;</code></strong>；<strong><code>autoDetect</code></strong> 默认 <strong><code>true</code></strong>（与 <strong>C7Preview</strong> 默认一致即可）。单元格内缩略尺寸通过 <strong>C7Preview 已有 props</strong>（如 <strong><code>width</code>/<code>height</code>/class</strong>）在列对象扩展字段上传入（文档给出一组推荐默认值）。</td></tr><tr><td><strong><code>link</code></strong></td><td><strong><code>&lt;a&gt;</code></strong>。<strong><code>linkHref</code> / <code>linkText</code></strong>： <strong><code>string</code></strong> 或 <strong><code>(row, column, cellValue, index) =&gt; string</code></strong>（<strong>3B</strong>）。<strong><code>linkTarget</code></strong>：首版仅 <strong><code>string</code></strong>（如 <strong><code>_blank</code></strong>），不传则 <strong>不设 <code>target</code></strong>。<strong>解析后 <code>href</code> 为空串 / <code>null</code> / <code>undefined</code></strong>：不渲染可点击链接，展示 <strong><code>-</code></strong>（与 <strong>text</strong> 空占位视觉一致）。</td></tr><tr><td><strong><code>slot</code></strong></td><td>具名 slot 名：**`slotName</td></tr></tbody></table></div><p><strong>未知 <code>columnType</code></strong>：按 <strong><code>text</code></strong> 处理，<strong>开发环境 <code>console.warn</code></strong>。</p><h3 id="_4-4-列头-slot" tabindex="-1">4.4 列头 slot <a class="header-anchor vp-link" href="#_4-4-列头-slot" aria-label="Permalink to &quot;4.4 列头 slot&quot;">​</a></h3><ul><li>命名：<strong><code>header-${prop}</code></strong>（对应需求 <strong><code>#header-[prop]</code></strong>）。</li><li><strong>前提</strong>：列必须具备 <strong><code>prop</code></strong>；无 <strong><code>prop</code></strong> 的列 <strong>不支持</strong> 该具名插槽（列头仅 <strong><code>label</code></strong> 或 EP 默认行为）。</li></ul><hr><h2 id="_5-插槽转发约定" tabindex="-1">5. 插槽转发约定 <a class="header-anchor vp-link" href="#_5-插槽转发约定" aria-label="Permalink to &quot;5. 插槽转发约定&quot;">​</a></h2><ul><li><strong>单元格（<code>slot</code> 类型）</strong>：<strong><code>C7JsonTableColumn</code></strong> 在对应 <strong><code>el-table-column</code></strong> 的 <strong><code>#default</code></strong> 内 <strong><code>&lt;slot :name=&quot;slotName&quot; v-bind=&quot;scope&quot; /&gt;</code></strong>，其中 <strong><code>slotName = col.slotName || col.prop</code></strong>。</li><li><strong>列头</strong>：若父级提供了 <strong><code>#header-${prop}</code></strong>，则在 <strong><code>el-table-column</code> 的 <code>#header</code></strong> 中转发 <strong><code>v-bind=&quot;headerScope&quot;</code></strong>；<strong><code>headerScope</code> 以 Element Plus 当前 <strong><code>ElTableColumn</code> header 插槽</strong> 类型为准</strong>（实现阶段以 EP 类型定义或文档为准写入 JSDoc）。若未提供该插槽，则使用 <strong><code>label</code></strong> 作为默认列头文本（有 <strong><code>label</code></strong> 时）。</li></ul><h3 id="_5-1-父组件用法示例-语义" tabindex="-1">5.1 父组件用法示例（语义） <a class="header-anchor vp-link" href="#_5-1-父组件用法示例-语义" aria-label="Permalink to &quot;5.1 父组件用法示例（语义）&quot;">​</a></h3><div class="language-vue vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">&lt;</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">el-table</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> :</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">data</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">=</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">&quot;</span><span style="--shiki-light:#B07D48;--shiki-dark:#BD976A;">rows</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">  &lt;C7JsonTableColumn :columns=&quot;columns&quot; :empty-text=&quot;&#39;—&#39;&quot;&gt;</span></span>\n<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    &lt;template #header-username=&quot;{ column }&quot;&gt;…&lt;/template&gt;</span></span>\n<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    &lt;template #action=&quot;{ row, $index }&quot;&gt;…&lt;/template&gt;</span></span>\n<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">  &lt;/C7JsonTableColumn&gt;</span></span>\n<span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">&lt;/</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">el-table</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>（具体 <strong><code>header</code> 作用域字段名</strong> 以实现时 EP 版本为准，不在此伪代码中写死错误字段。）</p><hr><h2 id="_6-text-与-formatter-的互斥语义-实现必守" tabindex="-1">6. <code>text</code> 与 <code>formatter</code> 的互斥语义（实现必守） <a class="header-anchor vp-link" href="#_6-text-与-formatter-的互斥语义-实现必守" aria-label="Permalink to &quot;6. `text` 与 `formatter` 的互斥语义（实现必守）&quot;">​</a></h2><ul><li><strong>存在 <code>formatter</code></strong>：<strong>完全遵循 EP</strong>，不在组件内对返回值再做「空值改 <code>emptyText</code>」处理。</li><li><strong>不存在 <code>formatter</code></strong>：走 <strong>第 4.3 节 <code>text</code></strong> 的空值与 <strong><code>emptyText</code> / 表级默认 / <code>&#39;-&#39;</code></strong> 规则。</li></ul><hr><h2 id="_7-与依赖组件的契约" tabindex="-1">7. 与依赖组件的契约 <a class="header-anchor vp-link" href="#_7-与依赖组件的契约" aria-label="Permalink to &quot;7. 与依赖组件的契约&quot;">​</a></h2><ul><li><strong>C7DictTag</strong>：仅只读展示；列配置 <strong><code>options</code>/<code>dictList</code></strong> 须为数组；不匹配行为以 <strong>C7DictTag</strong> 既有逻辑为准。</li><li><strong>C7Preview</strong>：表格内 <strong><code>coverType</code> 不为 <code>button</code></strong>，避免嵌套表格内再叠「仅按钮」交互造成理解成本；若业务需要按钮式预览，在 <strong><code>slot</code></strong> 列自行组合。</li></ul><hr><h2 id="_8-错误处理与边界" tabindex="-1">8. 错误处理与边界 <a class="header-anchor vp-link" href="#_8-错误处理与边界" aria-label="Permalink to &quot;8. 错误处理与边界&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>场景</th><th>行为</th></tr></thead><tbody><tr><td><strong><code>columns</code> 非数组</strong></td><td>不渲染；<strong>dev warn</strong>。</td></tr><tr><td><strong><code>columns</code> 为空数组</strong></td><td>无列，合法。</td></tr><tr><td><strong><code>slot</code> 类型但未提供对应插槽</strong></td><td>单元格展示 <strong><code>-</code></strong>（便于发现配置遗漏）。</td></tr><tr><td><strong><code>tag</code>/<code>image</code>/<code>link</code>/<code>text</code> 无 <code>prop</code></strong></td><td><strong><code>tag</code>/<code>image</code>/<code>text</code></strong>：<strong>dev warn</strong>，该列跳过渲染；<strong><code>link</code></strong>：无 <strong><code>prop</code></strong> 时 <strong><code>cellValue</code></strong> 无法定义——<strong>dev warn</strong> 并跳过该列（与「链接列需绑定字段」一致）。</td></tr></tbody></table></div><hr><h2 id="_9-验收与测试建议" tabindex="-1">9. 验收与测试建议 <a class="header-anchor vp-link" href="#_9-验收与测试建议" aria-label="Permalink to &quot;9. 验收与测试建议&quot;">​</a></h2><ul><li><strong>各 <code>columnType</code></strong> 渲染结果与 <strong>第 4.3 节</strong> 一致；<strong><code>dictList</code> vs <code>options</code></strong> 优先级可测。</li><li><strong><code>formatter</code></strong>：与 EP 签名一致且生效；<strong>有 <code>formatter</code> 时</strong> 不出现组件强加的 <strong><code>emptyText</code></strong> 覆盖。</li><li><strong>具名 slot</strong>：<strong><code>#default</code></strong> 作用域为 <strong><code>row, column, $index</code></strong>；<strong><code>#header-${prop}</code></strong> 可覆盖列头。</li><li><strong>排序</strong>：<strong><code>order</code> 未设置</strong>在后；同 <strong><code>order</code></strong> 保持输入顺序。</li><li><strong>E2E</strong>：新增 <strong><code>C7JsonTableColumnE2E</code></strong>（或等价 dev 页）+ 路由，覆盖上表关键路径。</li><li><strong>可选单测</strong>：若抽出 <strong><code>normalizeColumns</code></strong>，则对其过滤与稳定排序编写单测。</li></ul><hr><h2 id="_10-文档" tabindex="-1">10. 文档 <a class="header-anchor vp-link" href="#_10-文档" aria-label="Permalink to &quot;10. 文档&quot;">​</a></h2><ul><li><strong>VitePress</strong>：在与其它 C7 通用组件一致的目录下增加 <strong>C7JsonTableColumn</strong> 说明（<strong>Props / 列配置表 / 示例 / 与 C7JsonTable 关系</strong>）。</li></ul><hr><h2 id="_11-后续流程" tabindex="-1">11. 后续流程 <a class="header-anchor vp-link" href="#_11-后续流程" aria-label="Permalink to &quot;11. 后续流程&quot;">​</a></h2><ul><li>实现前：由 <strong><code>writing-plans</code></strong> 产出实现计划（含 <strong><code>packages/index.js</code> 注册</strong>、<strong>E2E 页</strong>、<strong>与 C7Preview/C7DictTag 联调</strong>）。</li><li>本文档经用户审阅文件无修改诉求后，再进入编码阶段。</li></ul>',50)])])}const u=t(r,[["render",d]]);export{h as __pageData,u as default};
